questions.solution:
class AppError(Exception):
    pass

class NotFound(AppError):
    pass

class Forbidden(AppError):
    pass

def fetch(page):
    if page == "missing":
        raise NotFound(page)
    if page == "admin":
        raise Forbidden(page)
    return f"Content of {page}"

tests.code:
for page, kind in (('missing', NotFound), ('admin', Forbidden)):
    try:
        fetch(page)
    except AppError as e:
        assert type(e) is kind, f'fetch("{page}") should raise {kind.__name__}.'
    else:
        raise AssertionError(f'fetch("{page}") should raise an error.')

