questions.solution:
class InsufficientFunds(Exception):
    pass

def withdraw(balance, amount):
    if amount <= 0:
        raise ValueError("amount must be positive")
    if amount > balance:
        raise InsufficientFunds(f"balance is only {balance}")
    return balance - amount

tests.code:
try:
    withdraw(100, 0)
except ValueError:
    pass
else:
    raise AssertionError('An amount of 0 or less should raise ValueError.')

try:
    withdraw(20, 25)
except InsufficientFunds:
    pass
else:
    raise AssertionError('Withdrawing more than the balance should raise InsufficientFunds.')
